const NoiseOverlay: React.FC<{ opacity: number }> = ({ opacity }) => {
  return (
    <AbsoluteFill
      style={{
        opacity,
        backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='1'/%3E%3C/svg%3E")`,
        mixBlendMode: "overlay",
        pointerEvents: "none",
      }}
    />
  );
};

const VideoPlaceholder: React.FC<{
  label: string;
  delay: number;
  width: number;
  accentColor: string;
  textColor: string;
}> = ({ label, delay, width, accentColor, textColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Entrance Spring
  const spr = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Continuous "Breathing" for interactivity hint
  const breath = Math.sin((frame - delay) / 20) * 0.01 + 1; // Slight scale oscillation
  
  // Calculate placeholder dimensions (16:9 ratio)
  const pWidth = width * 0.4;
  const pHeight = pWidth * (9 / 16);

  const containerStyle: React.CSSProperties = {
    width: pWidth,
    height: pHeight,
    backgroundColor: "rgba(255, 255, 255, 0.05)",
    border: `2px solid ${accentColor}`,
    borderRadius: 12,
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    position: "relative",
    transform: `scale(${spr * breath})`,
    opacity: Math.min(spr, 1),
    boxShadow: `0 0 20px ${accentColor}40`, // Soft glow
  };

  return (
    <div style={{ marginBottom: 40, position: "relative" }}>
      <div style={containerStyle}>
        {/* Inner dashed border for "Drop Zone" feel */}
        <div
          style={{
            position: "absolute",
            top: 10,
            left: 10,
            right: 10,
            bottom: 10,
            border: "2px dashed rgba(255,255,255,0.2)",
            borderRadius: 8,
          }}
        />
        {/* Placeholder Icon */}
        <svg
          width="48"
          height="48"
          viewBox="0 0 24 24"
          fill="none"
          stroke={accentColor}
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ opacity: 0.6 }}
        >
          <polygon points="5 3 19 12 5 21 5 3" />
        </svg>
      </div>
      
      {/* Label */}
      <h3
        style={{
          fontFamily: "Oswald",
          color: textColor,
          textTransform: "uppercase",
          fontSize: 24,
          letterSpacing: 2,
          marginTop: 12,
          marginLeft: 4,
          opacity: Math.min(spr, 1),
          textShadow: "0 2px 10px rgba(0,0,0,0.8)",
        }}
      >
        {label}
      </h3>
    </div>
  );
};

// ------------------------------------------------------------------
// 4. MAIN COMPONENT
